339	// Main API catch-all -- manual routing through cached route definitions
340	app.all("/api/*", async (c) => {
341	  const { compiled, db, storage } = getCompiledRoutes(c.env);
342	  const pathname = new URL(c.req.url).pathname;
343	  const method = c.req.method.toUpperCase();
344	
345	  for (const { route, re, paramNames } of compiled) {
346	    if (route.method !== method) continue;
347	    const match = re.exec(pathname);
348	    if (!match) continue;
349	
350	    // Build param map for this match
351	    const params: Record<string, string> = {};
352	    for (let i = 0; i < paramNames.length; i++) {
353	      params[paramNames[i]!] = match[i + 1]!;
354	    }
355	
356	    // Wrap ctx.param to return from our extracted params
357	    const actor = await resolveActorFromRequest(
358	      c.req.raw,
359	      db,
360	      {
361	        deploymentMode: c.env.DEPLOYMENT_MODE === "local_trusted"
362	          ? "local_trusted"
363	          : "authenticated",
364	      },
365	    );
366	
367	    const ctx: import("../../../server/src/http/types.js").RequestCtx = {
368	      method: c.req.method,
369	      url: new URL(c.req.url),
370	      headers: new Headers(c.req.raw.headers),
371	      json<T>(): Promise<T> { return c.req.json<T>(); },
372	      text(): Promise<string> { return c.req.text(); },
373	      param(name: string): string | undefined { return params[name]; },
374	      query(name: string): string | undefined { return c.req.query(name); },
375	      actor,
376	      db,
377	      storage,
378	    };
379	
380	    try {
381	      return await route.handler(ctx);
382	    } catch (err) {
383	      if (err instanceof HttpError) {
384	        return Response.json(
385	          { error: err.message, ...(err.details !== undefined ? { details: err.details } : {}) },
386	          { status: err.status },
387	        );
388	      }
389	      console.error(
390	        `[CF Worker] Unhandled error in ${route.method} ${route.path}: ${
391	          err instanceof Error ? err.stack ?? err.message : String(err)
392	        }`,
393	      );
394	      return Response.json({ error: "Internal Server Error" }, { status: 500 });
395	    }
396	  }
397	
398	  // No route matched
399	  return c.json(
400	    {
401	      error: "This API route is not available in the Cloudflare Workers deployment.",
402	      code: "NOT_IMPLEMENTED",
403	    },
404	    501,
405	  );
406	});
